package com.marcuspage.mentalpower

/**
 * Level data for Mental Power.
 *
 * Rooms 1 to 36 are the rooms of the original game: the shape of each and the set of
 * pieces handed to the player. Rooms 37 to 60 are new puzzles made for this app, each
 * one a shape that the pieces it hands out are known to fill.
 *
 * A room is solved when every cell of the shape is covered.
 */
object Levels {

    /** Canonical orientation of every piece, as rows of '#' (filled) and '.' (empty). */
    val PIECE_SHAPES: List<List<String>> = listOf(
        listOf("##", "##"),  // 1 O
        listOf("..#", "..#", "###"),  // 2 V
        listOf("##.", ".#.", ".##"),  // 3 Z
        listOf("#..", "###", "#.."),  // 4 T
        listOf(".#.", "##.", ".##"),  // 5 F
        listOf("#####"),  // 6 I
        listOf("..##", "###."),  // 7 N
        listOf("#..", "##.", ".##"),  // 8 W
        listOf("###", "#.#"),  // 9 U
        listOf("#.", "##", "##"),  // 10 P
        listOf(".#.", "###", ".#."),  // 11 X
        listOf("...#", "####"),  // 12 L
        listOf("..#.", "####"),  // 13 Y
    )

    val PIECE_NAMES: List<String> = listOf("O","V","Z","T","F","I","N","W","U","P","X","L","Y")

    /** One room. [rows] is the shape; '#' is a cell that must be filled. */
    class Level(
        val number: Int,
        val rows: List<String>,
        val pieces: List<Int>,   // indices into PIECE_SHAPES
        val password: String,
        /** True for the rooms that are not part of the original game. */
        val extra: Boolean = false,
    ) {
        val w: Int get() = rows[0].length
        val h: Int get() = rows.size
    }

